// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    // fuzz: from address and a list of recipients (encoded as bytes to produce variable-length arrays via fuzzer)
    function testFuzz_property(address from, bytes memory tosEncoded, uint256 v) public {
        // Decode tosEncoded into address[] in a simple way: treat as sequence of 20-byte words
        // Keep at least one recipient to be in admissible domain
        uint256 maxRecipients = 10;
        uint256 available = tosEncoded.length / 20;
        uint256 len = available;
        if (len == 0) { len = 1; }
        if (len > maxRecipients) { len = maxRecipients; }

        address[] memory tos = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            uint256 offset = i * 20;
            bytes20 b;
            assembly {
                b := mload(add(add(tosEncoded, 0x14), offset))
            }
            tos[i] = address(uint160(uint256(uint160(b))));
            // avoid zero-address recipient because it might be treated specially by some callees
            if (tos[i] == address(0)) {
                tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, v)))));
            }
        }

        // Deploy recorder helper that implements transferFrom(address,address,uint256)
        Recorder rec = new Recorder();

        // call c.transfer with recorder as callee address
        // c will low-level call rec.transferFrom(...). Recorder records calls in order.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty tos, the reference implementation invokes the callee for tos[0],
        // so the recorder's firstRecorded flag for index 0 must be true whenever the call completed.
        // The mutant that skips i=0 will leave that entry false for some inputs (and the fuzzer will find one).

        // We assert that if c.transfer returned (did not revert) then the recorder observed a call for index 0.
        // (This reads only recorder's public view which is the observable effect of c calling out.)
        if (ok) {
            // require that recorder saw at least one call and the first recorded target equals tos[0]
            // recorder.hasCallForIndex(0) returns true iff it got called with index 0 as recorded
            assertTrue(rec.hasCallForIndex(0), "reference: must have called tos[0]");
            // additionally check the arguments recorded match expectation
            (address recordedFrom, address recordedTo, uint256 recordedV) = rec.getCall(0);
            assertTrue(recordedFrom == from, "recorded from mismatch");
            assertTrue(recordedTo == tos[0], "recorded to[0] mismatch");
            assertTrue(recordedV == v, "recorded v mismatch");
        } else {
            // If transfer reverted, we cannot make claims about calls; still satisfy universal property by not asserting
        }
    }
}

// Recorder observes calls made with selector transferFrom(address,address,uint256)
contract Recorder {
    struct Call { address from; address to; uint256 v; }
    Call[] public calls;

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls.push(Call({from: from, to: to, v: v}));
        return true;
    }

    // helper to check whether a call at index i exists
    function hasCallForIndex(uint256 i) external view returns (bool) {
        return i < calls.length;
    }

    // getter to read recorded call arguments
    function getCall(uint256 i) external view returns (address, address, uint256) {
        Call storage c = calls[i];
        return (c.from, c.to, c.v);
    }
}
